import {seed,validate,query,descendants,errorsFor,storageKey,statuses,types} from './model.js';
const $=id=>document.getElementById(id);
const element=(tag,text='',parent)=>{const node=document.createElement(tag);node.textContent=text;if(parent)parent.append(node);return node;};
const button=(label,parent,action,cls='')=>{const node=element('button',label,parent);node.type='button';node.className=cls;node.onclick=action;return node;};
let state,loadNotice='';try{const raw=localStorage.getItem(storageKey);state=raw?validate(JSON.parse(raw)):seed();}catch{state=seed();loadNotice='Saved prototype data could not be read. A fresh demo is loaded; export before closing if storage stays unavailable.';}
let filter={search:'',collection:'',status:'',type:'',sort:'title',direction:1,trash:false},selected=new Set(['TERM-0001']),active='TERM-0001',page=0,layout='table',inspector='metadata',screen='catalog';
const perPage=8;
function announce(text){$('status').textContent=text;}
function persist(text){try{localStorage.setItem(storageKey,JSON.stringify(state));announce(text||'Prototype changes saved on this device.');}catch{announce('Browser storage is unavailable or full. Changes remain in this tab; use Export to save a copy.');}}
function log(record,text){record.activity.push({text,at:new Date().toISOString()});record.activity=record.activity.slice(-100);}
function icon(record,parent){const node=element('span',record.title.slice(0,1),parent);node.className='term-icon '+record.type.toLowerCase();node.setAttribute('aria-hidden','true');return node;}
function badge(status,parent){const node=element('span',status,parent);node.className='badge '+(status==='Ready'?'':status==='Draft'?'draft':'review');return node;}
function options(select,values,value){select.replaceChildren();for(const [id,label]of values){const option=element('option',label,select);option.value=id;}select.value=value;}
function collectionOptions(){return [['','Unassigned'],...state.collections.map(c=>[c.id,(c.parent?'↳ ':'')+c.name])];}
function field(label,name,value,parent,{kind='input',options:choices,type='text',wide=false}={}){const row=element('label',label,parent);row.className='editor-row'+(wide?' wide':'');const input=element(kind,'',row);input.name=name;if(kind==='select')options(input,choices,value);else{input.value=value??'';if(kind==='input')input.type=type;}return input;}
function modal(title,make,onSubmit,submitText='Save'){
 $('modalTitle').textContent=title;$('modalFields').replaceChildren();$('modalError').textContent='';$('modalSubmit').textContent=submitText;$('modalSubmit').hidden=!onSubmit;$('cancelModal').textContent=onSubmit?'Cancel':'Close';
 make($('modalFields'));$('modalForm').onsubmit=e=>{e.preventDefault();try{if(onSubmit?.(new FormData($('modalForm')))!==false)$('modal').close();}catch(error){$('modalError').textContent=error.message;}};
 $('modal').showModal();
}
$('closeModal').onclick=$('cancelModal').onclick=()=>$('modal').close();
function saveView(){modal('Save this view',root=>{field('View name','name','',root);element('p','Stores the current collection, search, filters and sorting.',root);},data=>{const name=String(data.get('name')).trim();if(!name)throw Error('Enter a view name.');state.views.push({name:name.slice(0,80),...filter});persist('View saved.');renderViews();});}
function addCollection(){modal('New collection',root=>{field('Collection name','name','',root);field('Parent collection','parent',filter.collection,root,{kind:'select',options:collectionOptions().map(([id,name])=>[id,id?name:'Top level'])});},data=>{const name=String(data.get('name')).trim();if(!name)throw Error('Enter a collection name.');const id=crypto.randomUUID();state.collections.push({id,name:name.slice(0,80),parent:String(data.get('parent'))});filter.collection=id;page=0;persist('Collection created.');render();});}
function addRecord(){modal('Add glossary record',root=>{field('Title','title','',root);field('Record type','type','Mechanic',root,{kind:'select',options:types.map(v=>[v,v])});field('Collection','collection',filter.collection,root,{kind:'select',options:collectionOptions()});field('Short definition','definition','',root,{kind:'textarea',wide:true});},data=>{const title=String(data.get('title')).trim();if(!title)throw Error('A title is required.');const record={id:'TERM-'+crypto.randomUUID().slice(0,8).toUpperCase(),title:title.slice(0,160),type:String(data.get('type')),collection:String(data.get('collection')),definition:String(data.get('definition')).slice(0,5000),subtitle:'New glossary entry',tags:[],aliases:[],status:'Draft',source:'Demo editorial example',sourceUrl:'',metadata:{},relations:[],activity:[],deleted:false};log(record,'Created record');state.records.push(record);filter={...filter,search:'',status:'',type:'',trash:false};$('search').value='';active=record.id;selected=new Set([active]);page=0;screen='catalog';persist('Record created. Add source details in the inspector.');render();});}
function addField(){modal('Configure metadata field',root=>{field('Field label','label','',root);field('Value type','type','text',root,{kind:'select',options:[['text','Text'],['number','Number'],['url','URL']]});field('Required','required','no',root,{kind:'select',options:[['no','Optional'],['yes','Required']]});},data=>{const label=String(data.get('label')).trim();if(!label)throw Error('Enter a field label.');if(state.fields.length>=30)throw Error('This concept supports 30 custom fields.');state.fields.push({id:'field-'+crypto.randomUUID().slice(0,8),label:label.slice(0,80),type:String(data.get('type')),required:data.get('required')==='yes'});persist('Metadata schema updated.');renderInspector();});}
function download(recordsOnly=false){const payload=recordsOnly?{...state,records:state.records.filter(r=>selected.has(r.id))}:state;const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=recordsOnly?'catalogix-selected.json':'catalogix-concept.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce(recordsOnly?'Selected records exported.':'Prototype snapshot exported.');}
function bulkChange(kind){if(!selected.size)return;modal(kind==='collection'?'Move selected records':'Set selected status',root=>{field(kind==='collection'?'Collection':'Status','value',kind==='collection'?filter.collection:'In review',root,{kind:'select',options:kind==='collection'?collectionOptions():statuses.map(v=>[v,v])});element('p',`${selected.size} selected record${selected.size===1?'':'s'} will be updated.`,root);},data=>{const value=String(data.get('value'));for(const r of state.records)if(selected.has(r.id)){r[kind]=value;log(r,kind==='collection'?'Moved to another collection':`Status changed to ${value}`);}persist('Selected records updated.');render();});}
function renderViews(){const root=$('savedViews');root.replaceChildren();if(!state.views.length)element('p','Save filters you use often.',root).className='empty-saved';for(const view of state.views)button(view.name,root,()=>{filter={...filter,...view,trash:false};$('search').value=filter.search;page=0;screen='catalog';render();},'saved-view');}
function renderCollections(){const root=$('collectionTree');root.replaceChildren();const needle=$('collectionSearch').value.toLowerCase();
 function node(id,name,depth){if(needle&&!name.toLowerCase().includes(needle))return;const matches=descendants(state.collections,id);const count=state.records.filter(r=>!r.deleted&&(!id||matches.has(r.collection))).length;const b=button('',root,()=>{filter.collection=id;filter.trash=false;screen='catalog';page=0;render();},'collection-node depth-'+depth+(filter.collection===id&&!filter.trash?' selected':''));element('span','▱',b).className='folder';element('span',name,b);element('span',String(count),b).className='count';b.setAttribute('aria-pressed',String(filter.collection===id&&!filter.trash));}
 node('','All records',0);function children(parent,depth){for(const c of state.collections.filter(c=>c.parent===parent)){node(c.id,c.name,depth);children(c.id,depth+1);}}children('',0);
}
function renderMetrics(){const records=state.records.filter(r=>!r.deleted);$('totalMetric').textContent=records.length;$('collectionMetric').textContent=state.collections.length;$('tagMetric').textContent=new Set(records.flatMap(r=>r.tags)).size;$('readyMetric').textContent=records.filter(r=>r.status==='Ready').length;$('reviewBadge').textContent=records.filter(r=>r.status==='In review').length;}
function choose(record){active=record.id;selected=new Set([record.id]);renderRecords();renderInspector();}
function check(record,checked){if(checked)selected.add(record.id);else selected.delete(record.id);active=record.id;renderRecords();renderInspector();}
function renderRecords(){const root=$('records');root.replaceChildren();const matches=query(state,filter),pages=Math.max(1,Math.ceil(matches.length/perPage));page=Math.min(page,pages-1);const visible=matches.slice(page*perPage,(page+1)*perPage);$('resultCount').textContent=`${matches.length} records`;$('pageCount').textContent=`${page+1} / ${pages}`;$('previous').disabled=page===0;$('next').disabled=page===pages-1;$('selectionCount').textContent=`${selected.size} selected`;for(const id of ['bulkCollection','bulkStatus','bulkExport'])$(id).disabled=!selected.size;
 if(screen==='taxonomy'){const wrap=element('div','',root);wrap.className='taxonomy';element('h3','Tag taxonomy',wrap);element('p','Choose a tag to search its records.',wrap).className='meta-hint';for(const tag of [...new Set(state.records.filter(r=>!r.deleted).flatMap(r=>r.tags))].sort())button(`${tag} · ${state.records.filter(r=>!r.deleted&&r.tags.includes(tag)).length}`,wrap,()=>{filter.search=tag;$('search').value=tag;screen='catalog';page=0;render();},'tag');return;}
 if(!visible.length){element('p','No records match this view. Clear the filters or add a record.',root).className='empty-results';return;}
 if(layout==='cards'){const cards=element('div','',root);cards.className='cards';for(const r of visible){const card=element('article','',cards);card.className='record-card'+(selected.has(r.id)?' selected':'');card.tabIndex=0;card.setAttribute('aria-label',r.title);card.onclick=()=>choose(r);card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(r);}};icon(r,card);element('h3',r.title,card);element('small',r.id,card);element('p',r.definition.slice(0,120),card);badge(r.status,card);}return;}
 const table=element('table','',root),thead=element('thead','',table),head=element('tr','',thead);let th=element('th','',head);const all=element('input','',th);all.type='checkbox';all.setAttribute('aria-label','Select visible records');all.checked=visible.every(r=>selected.has(r.id));all.indeterminate=!all.checked&&visible.some(r=>selected.has(r.id));all.onchange=()=>{for(const r of visible)if(all.checked)selected.add(r.id);else selected.delete(r.id);renderRecords();};element('th','',head);
 for(const [id,label]of [['title','Title'],['id','ID'],['type','Type'],['status','Status']]){th=element('th','',head);if(id==='id')th.className='id-cell';if(id==='type')th.className='type-cell';button(label+(filter.sort===id?(filter.direction===1?' ↑':' ↓'):''),th,()=>{filter.direction=filter.sort===id?-filter.direction:1;filter.sort=id;renderRecords();});}
 const tbody=element('tbody','',table);for(const r of visible){const tr=element('tr','',tbody);tr.className=selected.has(r.id)?'selected':'';tr.onclick=()=>choose(r);let td=element('td','',tr);const cb=element('input','',td);cb.type='checkbox';cb.checked=selected.has(r.id);cb.setAttribute('aria-label',`Select ${r.title}`);cb.onclick=e=>e.stopPropagation();cb.onchange=()=>check(r,cb.checked);icon(r,element('td','',tr));td=element('td','',tr);td.className='title-cell';const open=button(r.title,td,()=>choose(r),'record-title');open.style.cssText='background:none;border:0;padding:0;text-align:left;white-space:normal';element('span',r.subtitle,td).className='record-subtitle';element('td',r.id,tr).className='id-cell';element('td',r.type,tr).className='type-cell';badge(r.status,element('td','',tr));}
}
function renderInspector(){const root=$('inspectorContent');root.replaceChildren();const record=state.records.find(r=>r.id===active);if(!record){element('p','Select a record to inspect its metadata.',root).className='empty-inspector';return;}const form=element('form','',root);const summary=element('div','',form);summary.className='record-summary';icon(record,summary);const text=element('div','',summary);element('h3',record.title,text);element('p',record.id,text).className='record-id';badge(record.deleted?'Archived':record.status,text);
 if(inspector==='metadata'){
 const core=element('div','',form);core.className='editor-section';element('h3','⌄ Core metadata',core);field('Title','title',record.title,core);field('Type','type',record.type,core,{kind:'select',options:types.map(v=>[v,v])});field('Collection','collection',record.collection,core,{kind:'select',options:collectionOptions()});field('Status','status',record.status,core,{kind:'select',options:statuses.map(v=>[v,v])});field('Definition','definition',record.definition,core,{kind:'textarea',wide:true});
 const tags=element('div','',form);tags.className='editor-section';element('h3','⌄ Tags & aliases',tags);const list=element('div','',tags);list.className='tag-list';record.tags.forEach(t=>element('span',t,list).className='tag');field('Tags','tags',record.tags.join(', '),tags,{wide:true});field('Aliases','aliases',record.aliases.join(', '),tags,{wide:true});element('p','Separate values with commas.',tags).className='meta-hint';
 const source=element('div','',form);source.className='editor-section';element('h3','⌄ Source & schema',source);field('Source','source',record.source,source);field('URL','sourceUrl',record.sourceUrl,source,{type:'url'});for(const f of state.fields)field(f.label+(f.required?' *':''),'meta:'+f.id,record.metadata[f.id]||'',source,{type:f.type==='text'?'text':f.type});button('＋ Configure metadata field',source,addField);element('p','Demo definitions are illustrative and need source verification.',source).className='meta-hint';
 const error=element('p','',form);error.className='form-error';error.setAttribute('role','alert');const actions=element('div','',form);actions.className='inspector-actions';button(record.deleted?'Restore':'Archive',actions,()=>{record.deleted=!record.deleted;log(record,record.deleted?'Moved to trash':'Restored from trash');persist(record.deleted?'Record archived. Restore it from Trash.':'Record restored.');render();});const submit=element('button','Save changes',actions);submit.className='primary';submit.type='submit';form.onsubmit=e=>{e.preventDefault();const data=new FormData(form);const next={...record,title:String(data.get('title')).trim(),type:String(data.get('type')),collection:String(data.get('collection')),status:String(data.get('status')),definition:String(data.get('definition')).trim(),source:String(data.get('source')).trim(),sourceUrl:String(data.get('sourceUrl')).trim(),tags:[...new Set(String(data.get('tags')).split(',').map(t=>t.trim()).filter(Boolean))],aliases:[...new Set(String(data.get('aliases')).split(',').map(t=>t.trim()).filter(Boolean))],metadata:Object.fromEntries(state.fields.map(f=>[f.id,String(data.get('meta:'+f.id)||'').trim()]))};const errors=errorsFor(next,state.fields);if(errors.length){error.textContent=errors.join(' ');return;}Object.assign(record,next);log(record,'Metadata updated');persist('Metadata saved.');render();};
 }else if(inspector==='relations'){
 const section=element('div','',form);section.className='editor-section';element('h3','Related definitions',section);if(!record.relations.length)element('p','No relationships yet.',section).className='meta-hint';for(const id of record.relations){const r=state.records.find(r=>r.id===id);if(!r)continue;const row=element('div','',section);row.className='relation';button(r.title,row,()=>{active=r.id;selected=new Set([r.id]);render();});button('Remove',row,()=>{record.relations=record.relations.filter(v=>v!==id);log(record,'Removed a relationship');persist();renderInspector();});}const select=field('Link another record','relation','',section,{kind:'select',options:[['','Choose a record'],...state.records.filter(r=>!r.deleted&&r.id!==record.id&&!record.relations.includes(r.id)).map(r=>[r.id,r.title])],wide:true});button('＋ Add relationship',section,()=>{if(!select.value)return;record.relations.push(select.value);log(record,'Added a relationship');persist('Relationship saved.');renderInspector();});
 }else{const section=element('div','',form);section.className='editor-section';element('h3','Record activity',section);for(const item of record.activity.slice().reverse()){const entry=element('div',item.text,section);entry.className='activity-entry';const date=new Date(item.at);element('small',Number.isFinite(date.getTime())?date.toLocaleString():'Imported activity',entry);}}
}
function render(){const title=state.collections.find(c=>c.id===filter.collection)?.name||'Exile Compendium';$('pageTitle').textContent=filter.trash?'Archived records':screen==='taxonomy'?'Tag taxonomy':title;$('breadcrumb').textContent=filter.trash?'Trash':screen==='taxonomy'?'Taxonomy':filter.collection?title:'All records';$('pageDescription').textContent=filter.trash?'Archived prototype records can be restored from the inspector.':screen==='taxonomy'?'Browse the vocabulary used throughout your catalog.':'A connected library of mechanics, skills, and modifier language.';options($('statusFilter'),[['','Any status'],...statuses.map(v=>[v,v])],filter.status);options($('typeFilter'),[['','Any type'],...types.map(v=>[v,v])],filter.type);document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===screen));renderMetrics();renderCollections();renderViews();renderRecords();renderInspector();}
$('search').oninput=()=>{filter.search=$('search').value;page=0;screen='catalog';renderRecords();};$('collectionSearch').oninput=renderCollections;$('statusFilter').onchange=()=>{filter.status=$('statusFilter').value;page=0;renderRecords();};$('typeFilter').onchange=()=>{filter.type=$('typeFilter').value;page=0;renderRecords();};$('clearFilters').onclick=()=>{filter={...filter,search:'',status:'',type:'',collection:'',trash:false};screen='catalog';$('search').value='';page=0;render();};$('addRecord').onclick=addRecord;$('addCollection').onclick=addCollection;$('saveView').onclick=$('saveViewSmall').onclick=saveView;$('export').onclick=()=>download();$('bulkExport').onclick=()=>download(true);$('bulkCollection').onclick=()=>bulkChange('collection');$('bulkStatus').onclick=()=>bulkChange('status');$('previous').onclick=()=>{page--;renderRecords();};$('next').onclick=()=>{page++;renderRecords();};
for(const [id,mode]of [['tableView','table'],['gridView','cards']])$(id).onclick=()=>{layout=mode;$('tableView').setAttribute('aria-pressed',String(mode==='table'));$('gridView').setAttribute('aria-pressed',String(mode==='cards'));renderRecords();};
document.querySelectorAll('[data-inspector]').forEach(b=>b.onclick=()=>{inspector=b.dataset.inspector;document.querySelectorAll('[data-inspector]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));renderInspector();});
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{screen=b.dataset.nav;filter={...filter,trash:screen==='trash',collection:'',status:screen==='review'?'In review':'',type:'',search:''};$('search').value='';page=0;render();if(screen==='collections')$('collectionSearch').focus();});
$('import').onclick=()=>$('importFile').click();$('importFile').onchange=async()=>{const file=$('importFile').files[0];if(!file)return;try{if(file.size>5_000_000)throw Error('Choose a snapshot smaller than 5 MB.');const imported=validate(JSON.parse(await file.text()));modal('Import prototype snapshot',root=>{element('p',`Replace this prototype workspace with ${imported.records.length} records and ${imported.collections.length} collections? This affects only the separate Catalogix concept storage. Export first to keep your current prototype data.`,root);},()=>{state=imported;selected=new Set();active=state.records[0]?.id||'';filter={search:'',collection:'',status:'',type:'',sort:'title',direction:1,trash:false};$('search').value='';page=0;persist('Snapshot imported.');render();},'Import snapshot');}catch(error){announce('Import failed: '+error.message);}$('importFile').value='';};
function about(){modal('A new direction for the compendium',root=>{element('p','This is a standalone design concept inspired by the supplied orange Catalogix reference. It does not connect to or change the companion application.',root);element('p','Try creating records and nested collections, editing metadata, linking records, filtering, sorting, saving views, switching layouts, archiving/restoring records, and importing/exporting snapshots.',root);element('p','All records are illustrative demo content. Browser storage is isolated to this prototype. Ctrl+K focuses search; Escape closes dialogs. No external requests, cloud services or production data are used.',root);},null);}$('help').onclick=$('about').onclick=about;document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('search').focus();}});
render();if(loadNotice)announce(loadNotice);
